window.CODE_INDEX = {"classes":{"AltTextReminder":{"appearsIn":[["composer","h-widgets","Screen \u00b7 component composition"]],"code":"function AltTextReminder({error}: {error: string}) {\n  return (\n    <Admonition type=\"error\" style={[a.mt_2xs, a.mb_sm, a.mx_lg]}>\n      {error}\n    </Admonition>\n  )\n}","file":"src/view/com/composer/Composer.tsx","kind":"component","line":1985,"members":{"error":[1985,1985]},"supers":[]},"ComposePost":{"appearsIn":[["composer","h-classes","Logic \u00b7 class diagram"],["composer","h-widgets","Screen \u00b7 component composition"],["composer","h-sequence","Write and publish a thread \u00b7 sequence"],["index","h-screens","Screens \u00b7 how the user moves"]],"code":"export const ComposePost = ({\n  replyTo,\n  onPost,\n  onPostSuccess,\n  quote: initQuote,\n  quoteUri: initQuoteUri,\n  mention: initMention,\n  text: initText,\n  imageUris: initImageUris,\n  videoUri: initVideoUri,\n  openGallery,\n  logContext,\n  cancelRef,\n}: Props & {\n  cancelRef?: React.RefObject<CancelRef | null>\n}) => {\n  const {currentAccount} = useSession()\n  const t = useTheme()\n  const ax = useAnalytics()\n  const client = useAppviewClient()\n  const chatClient = useChatClient()\n  const pdsClient = usePdsClient()\n  const queryClient = useQueryClient()\n  /*\n   * The host the video service-auth token is minted for. This is the same value\n   * that seeds the session's PDS routing, so the audience always matches the host\n   * the upload actually reaches; a mismatch would 401 the upload.\n   */\n  const currentDispatchUrl = currentAccount!.pdsUrl ?? currentAccount!.service\n  const {closeComposer} = useComposerControls()\n  const {t: l, i18n} = useLingui()\n  const requireAltTextEnabled = useRequireAltTextEnabled()\n  const langPrefs = useLanguagePrefs()\n  const setLangPrefs = useLanguagePrefsApi()\n  const textInputRef = useRef<TextInputRef>(null)\n  const discardPromptControl = Prompt.usePromptControl()\n  const emptyPostsPromptControl = Prompt.usePromptControl()\n  const skipEmptyConfirmedRef = useRef(false)\n  const {mutateAsync: saveDraft, isPending: isSavingDraft} =\n    useSaveDraftMutation()\n  const {mutate: cleanupPublishedDraft} = useCleanupPublishedDraftMutation()\n  const {closeAllDialogs} = useDialogStateControlContext()\n  const {data: preferences} = usePreferencesQuery()\n  const navigation = useNavigation<NavigationProp>()\n\n  const [isPublishing, setIsPublishing] = useState(false)\n  const [publishingStage, setPublishingStage] = useState('')\n  const [error, setError] = useState('')\n\n  /**\n   * Track when a draft was created so we can measure draft age in metrics.\n   * Set when a draft is loaded via handleSelectDraft.\n   */\n  const [loadedDraftCreatedAt, setLoadedDraftCreatedAt] = useState<\n    string | null\n  >(null)\n\n  /**\n   * A manual selection or accepted suggestion applies only to this composer\n   * session, without changing the primary language preference.\n   */\n  const [selectedPostLanguage, setSelectedPostLanguage] = useState<\n    string | null\n  >(null)\n\n  /**\n   * The language(s) of the post being replied to.\n   */\n  const [replyToLanguages, setReplyToLanguages] = useState<string[]>(\n    replyTo?.langs || [],\n  )\n\n  /**\n   * Default to the primary language, ignoring the legacy sticky post language\n   * preference. Manual selections and accepted suggestions apply locally.\n   */\n  const currentLanguages = useMemo(\n    () =>\n      selectedPostLanguage\n        ? toPostLanguages(selectedPostLanguage)\n        : [langPrefs.primaryLanguage],\n    [selectedPostLanguage, langPrefs.primaryLanguage],\n  )\n\n  /**\n   * When the user selects a language from the composer language selector,\n   * override the current selection and clear reply language suggestions.\n   */\n  const onSelectLanguage = (language: string) => {\n    setSelectedPostLanguage(language)\n    setReplyToLanguages([])\n  }\n\n  /**\n   * Timestamp (ms) of the last honored nudge from language detection.\n   * Used to rate-limit the pulse animation: we ignore back-to-back\n   * nudges that arrive within NUDGE_COOLDOWN_MS. Consumers key an effect\n   * on this value \u2014 it only changes when we actually want to re-pulse.\n   */\n  const [languageNudgeAt, setLanguageNudgeAt] = useState(0)\n  const onLanguageNudge = () => {\n    const now = Date.now()\n    // ignore back-to-back nudges within 10s; only update state (and\n    // therefore re-pulse) once the cooldown has elapsed\n    setLanguageNudgeAt(prev => (now - prev > 10_000 ? now : prev))\n  }\n\n  const [composerState, composerDispatch] = useReducer(\n    composerReducer,\n    {\n      initImageUris,\n      initQuoteUri: initQuote?.uri ?? initQuoteUri,\n      initText,\n      initMention,\n      initInteractionSettings: preferences?.postInteractionSettings,\n    },\n    createComposerState,\n  )\n\n  const thread = composerState.thread\n\n  /*\n   * A quote opened by URI (from a deep link) skips the quote button's checks,\n   * so run them once the post resolves. When it can't be quoted, drop the\n   * quote and keep whatever else came with it.\n   */\n  const [uncheckedQuoteUri] = useState(() =>\n    initQuoteUri && !initQuote ? thread.posts[0].embed.quote?.uri : undefined,\n  )\n  const {data: uncheckedQuote, error: uncheckedQuoteError} = useQuery({\n    ...resolveLinkQueryOptions(\n      {appviewClient: client, chatClient},\n      uncheckedQuoteUri ?? '',\n    ),\n    enabled: !!uncheckedQuoteUri,\n  })\n  useEffect(() => {\n    if (!uncheckedQuoteUri) return\n    let problem: {message: string; type: 'error' | 'warning'} | undefined\n    if (uncheckedQuoteError) {\n      problem =\n        uncheckedQuoteError instanceof EmbeddingDisabledError\n          ? {\n              message: l`This post's author has disabled quote posts.`,\n              type: 'warning',\n            }\n          : {message: l`Couldn\u2019t load the post to quote`, type: 'error'}\n    } else if (\n      uncheckedQuote?.type === 'record' &&\n      uncheckedQuote.kind === 'post'\n    ) {\n      const author = uncheckedQuote.view.author.viewer\n      if (author?.blocking || author?.blockedBy || author?.blockingByList) {\n        problem = {\n          message: l`Cannot interact with a blocked user`,\n          type: 'warning',\n        }\n      }\n    }\n    if (!problem) return\n    const post = thread.posts.find(\n      p => p.embed.quote?.uri === uncheckedQuoteUri,\n    )\n    if (!post) return\n    composerDispatch({\n      type: 'update_post',\n      postId: post.id,\n      postAction: {type: 'embed_remove_quote'},\n    })\n    Toast.show(problem.message, {type: problem.type})\n  }, [uncheckedQuoteUri, uncheckedQuote, uncheckedQuoteError, thread, l])\n\n  // Clear error when composer content changes, but only if all posts are\n  // back within the character limit.\n  const allPostsWithinLimit = thread.posts.every(\n    post => post.richtext.graphemeLength <= MAX_DRAFT_GRAPHEME_LENGTH,\n  )\n\n  const activePost = thread.posts[composerState.activePostIndex]\n  const nextPost: PostDraft | undefined =\n    thread.posts[composerState.activePostIndex + 1]\n  const dispatch = useCallback(\n    (postAction: PostAction) => {\n      composerDispatch({\n        type: 'update_post',\n        postId: activePost.id,\n        postAction,\n      })\n    },\n    [activePost.id],\n  )\n\n  const selectVideo = useCallback(\n    async (postId: string, asset: ImagePickerAsset) => {\n      /*\n       * Share-extension deeplinks deliver a video URI without duration, so\n       * probe before we decide whether to compress. The picker and web paste\n       * paths already populate duration upstream. GIFs must skip the probe:\n       * they have no video track, so the iOS prober never resolves or rejects\n       * and the await below would hang forever.\n       */\n      if (\n        asset.duration == null &&\n        IS_NATIVE &&\n        asset.mimeType !== 'image/gif'\n      ) {\n        try {\n          const probed = await getVideoMetadata(asset.uri, asset.mimeType)\n          asset = {\n            ...asset,\n            mimeType: probed.mimeType ?? asset.mimeType,\n            width: probed.width ?? asset.width,\n            height: probed.height ?? asset.height,\n            duration: probed.duration,\n          }\n        } catch (e) {\n          logger.warn('selectVideo: duration probe failed', {safeMessage: e})\n        }\n      }\n\n      const abortController = new AbortController()\n      const telemetry = createVideoTelemetry({\n        asset,\n        signal: abortController.signal,\n        metric: ax.metric,\n      })\n      telemetry.picked()\n      composerDispatch({\n        type: 'update_post',\n        postId: postId,\n        postAction: {\n          type: 'embed_add_video',\n          asset,\n          abortController,\n          telemetry,\n        },\n      })\n\n      /*\n       * Fail early on duration so we don't spend time compressing a video the\n       * server would reject anyway.\n       */\n      if (asset.duration != null && asset.duration > VIDEO_MAX_DURATION_MS) {\n        composerDispatch({\n          type: 'update_post',\n          postId: postId,\n          postAction: {\n            type: 'embed_update_video',\n            videoAction: {\n              type: 'to_error',\n              error: l`Videos must be 10 minutes or less.`,\n              signal: abortController.signal,\n            },\n          },\n        })\n        return\n      }\n\n      void processVideo(\n        asset,\n        videoAction => {\n          composerDispatch({\n            type: 'update_post',\n            postId: postId,\n            postAction: {\n              type: 'embed_update_video',\n              videoAction,\n            },\n          })\n        },\n        pdsClient,\n        currentDispatchUrl,\n        abortController.signal,\n        i18n,\n        telemetry,\n      )\n    },\n    [l, i18n, pdsClient, currentDispatchUrl, composerDispatch, ax.metric],\n  )\n\n  const onInitVideo = useNonReactiveCallback(() => {\n    if (initVideoUri) {\n      void selectVideo(activePost.id, initVideoUri)\n    }\n  })\n\n  useEffect(() => {\n    onInitVideo()\n  }, [onInitVideo])\n\n  // Fire composer:open metric on mount\n  useCallOnce(() => {\n    ax.metric('composer:open', {\n      logContext: logContext ?? 'Other',\n      isReply: !!replyTo,\n      hasQuote: !!initQuote || !!initQuoteUri,\n      hasDraft: false,\n    })\n  })()\n\n  const clearVideo = useCallback(\n    (postId: string) => {\n      composerDispatch({\n        type: 'update_post',\n        postId: postId,\n        postAction: {\n          type: 'embed_remove_video',\n        },\n      })\n    },\n    [composerDispatch],\n  )\n\n  const restoreVideo = useCallback(\n    async (postId: string, videoInfo: RestoredVideo) => {\n      try {\n        logger.debug('restoring video from draft', {\n          postId,\n          videoUri: videoInfo.uri,\n          altText: videoInfo.altText,\n          captionCount: videoInfo.captions.length,\n        })\n\n        let asset: ImagePickerAsset\n\n        if (IS_WEB) {\n          // Web: Convert blob URL to a File, then get video metadata (returns data URL)\n          const response = await fetch(videoInfo.uri)\n          const blob = await response.blob()\n          const file = new File([blob], 'restored-video', {\n            type: videoInfo.mimeType,\n          })\n          asset = await getVideoMetadata(file)\n        } else {\n          let uri = videoInfo.uri\n          if (IS_ANDROID) {\n            // Android: expo-file-system double-encodes filenames with special chars.\n            // The native metadata probe can't handle the double-encoded URI, so\n            // copy it to a temp file with a simple name.\n            const sourceFile = new FileSystem.File(videoInfo.uri)\n            const tempFileName = `draft-video-${Date.now()}.${mimeToExt(videoInfo.mimeType)}`\n            const tempFile = new FileSystem.File(\n              FileSystem.Paths.cache,\n              tempFileName,\n            )\n            await sourceFile.copy(tempFile)\n            logger.debug('restoreVideo: copied to temp file', {\n              source: videoInfo.uri,\n              temp: tempFile.uri,\n            })\n            uri = tempFile.uri\n          }\n          asset = await getVideoMetadata(uri, videoInfo.mimeType)\n        }\n\n        // Start video processing using existing flow\n        const abortController = new AbortController()\n        const telemetry = createVideoTelemetry({\n          asset,\n          signal: abortController.signal,\n          metric: ax.metric,\n        })\n        telemetry.picked()\n        composerDispatch({\n          type: 'update_post',\n          postId,\n          postAction: {\n            type: 'embed_add_video',\n            asset,\n            abortController,\n            telemetry,\n          },\n        })\n\n        if (asset.duration != null && asset.duration > VIDEO_MAX_DURATION_MS) {\n          composerDispatch({\n            type: 'update_post',\n            postId,\n            postAction: {\n              type: 'embed_update_video',\n              videoAction: {\n                type: 'to_error',\n                error: l`Videos must be 10 minutes or less.`,\n                signal: abortController.signal,\n              },\n            },\n          })\n          return\n        }\n\n        // Restore alt text immediately\n        if (videoInfo.altText) {\n          composerDispatch({\n            type: 'update_post',\n            postId,\n            postAction: {\n              type: 'embed_update_video',\n              videoAction: {\n                type: 'update_alt_text',\n                altText: videoInfo.altText,\n                signal: abortController.signal,\n              },\n            },\n          })\n        }\n\n        // Restore captions (web only - captions use File objects)\n        if (IS_WEB && videoInfo.captions.length > 0) {\n          const captionTracks = videoInfo.captions.map(c => ({\n            lang: c.lang,\n            file: new File([c.content], `caption-${c.lang}.vtt`, {\n              type: 'text/vtt',\n            }),\n          }))\n          composerDispatch({\n            type: 'update_post',\n            postId,\n            postAction: {\n              type: 'embed_update_video',\n              videoAction: {\n                type: 'update_captions',\n                updater: () => captionTracks,\n                signal: abortController.signal,\n              },\n            },\n          })\n        }\n\n        // Start video compression and upload\n        void processVideo(\n          asset,\n          videoAction => {\n            composerDispatch({\n              type: 'update_post',\n              postId,\n              postAction: {\n                type: 'embed_update_video',\n                videoAction,\n              },\n            })\n          },\n          pdsClient,\n          currentDispatchUrl,\n          abortController.signal,\n          i18n,\n          telemetry,\n        )\n      } catch (e) {\n        logger.error('Failed to restore video from draft', {\n          postId,\n          error: e,\n        })\n      }\n    },\n    [l, i18n, pdsClient, currentDispatchUrl, composerDispatch, ax.metric],\n  )\n\n  const handleSelectDraft = useCallback(\n    async (draftSummary: DraftSummary) => {\n      logger.debug('loading draft for editing', {\n        draftId: draftSummary.id,\n      })\n\n      // Load local media files for the draft\n      const {loadedMedia} = await loadDraftMedia(draftSummary.draft)\n\n      // Extract original localRefs for orphan detection on save\n      const originalLocalRefs = extractLocalRefs(draftSummary.draft)\n\n      logger.debug('draft loaded', {\n        draftId: draftSummary.id,\n        loadedMediaCount: loadedMedia.size,\n        originalLocalRefCount: originalLocalRefs.size,\n      })\n\n      // Convert server draft to composer posts (videos returned separately)\n      const {posts, restoredVideos} = await draftToComposerPosts(\n        draftSummary.draft,\n        loadedMedia,\n      )\n\n      // Dispatch restore action (this also sets draftId in state)\n      composerDispatch({\n        type: 'restore_from_draft',\n        draftId: draftSummary.id,\n        posts,\n        threadgateAllow: draftSummary.draft.threadgateAllow,\n        postgateEmbeddingRules: draftSummary.draft.postgateEmbeddingRules,\n        loadedMedia,\n        originalLocalRefs,\n      })\n\n      // Track when the draft was created for metrics\n      setLoadedDraftCreatedAt(draftSummary.createdAt)\n\n      // Fire draft:load metric\n      const draftPosts = draftSummary.posts\n      const draftAgeMs = Date.now() - new Date(draftSummary.createdAt).getTime()\n      ax.metric('draft:load', {\n        draftAgeMs,\n        hasText: draftPosts.some(p => p.text.trim().length > 0),\n        hasImages: draftPosts.some(p => p.images && p.images.length > 0),\n        hasVideo: draftPosts.some(p => !!p.video),\n        hasGif: draftPosts.some(p => !!p.gif),\n        postCount: draftPosts.length,\n      })\n\n      // Initiate video processing for any restored videos\n      // This is async but we don't await - videos process in the background\n      for (const [postIndex, videoInfo] of restoredVideos) {\n        const postId = posts[postIndex].id\n        void restoreVideo(postId, videoInfo)\n      }\n    },\n    [composerDispatch, restoreVideo, ax],\n  )\n\n  const [publishOnUpload, setPublishOnUpload] = useState(false)\n\n  const onClose = useCallback(() => {\n    // HACKFIX: Android keyboard doesn't consistently dismiss IME\n    // TODO: investigate the root cause and fix properly -sfn\n    if (IS_ANDROID) {\n      Keyboard.dismiss()\n    }\n    closeComposer()\n    clearThumbnailCache(queryClient)\n    revokeAllMediaUrls()\n  }, [closeComposer, queryClient])\n\n  const getDraftSaveError = useCallback(\n    (e: unknown): string => {\n      if (\n        matchXrpcError(e, app.bsky.draft.createDraft) === 'DraftLimitReached'\n      ) {\n        return l`You've reached the maximum number of drafts`\n      }\n      return l`Failed to save draft`\n    },\n    [l],\n  )\n\n  const validateDraftTextOrError = useCallback((): boolean => {\n    const tooLong = composerState.thread.posts.some(\n      post => post.richtext.graphemeLength > MAX_DRAFT_GRAPHEME_LENGTH,\n    )\n    if (tooLong) {\n      setError(\n        l`One or more posts are too long to save as a draft. ${plural(MAX_DRAFT_GRAPHEME_LENGTH, {one: 'The maximum number of characters is # character.', other: 'The maximum number of characters is # characters.'})}`,\n      )\n      return false\n    }\n    return true\n  }, [composerState.thread.posts, l])\n\n  const handleSaveDraft = useCallback(async () => {\n    setError('')\n    if (!validateDraftTextOrError()) {\n      return\n    }\n    const isNewDraft = !composerState.draftId\n    try {\n      const result = await saveDraft({\n        composerState,\n        existingDraftId: composerState.draftId,\n      })\n      composerDispatch({type: 'mark_saved', draftId: result.draftId})\n\n      // Fire draft:save metric\n      const posts = composerState.thread.posts\n      ax.metric('draft:save', {\n        isNewDraft,\n        hasText: posts.some(p => p.richtext.text.trim().length > 0),\n        hasImages: posts.some(\n          p =>\n            p.embed.media?.type === 'images' ||\n            p.embed.media?.type === 'gallery',\n        ),\n        hasVideo: posts.some(p => p.embed.media?.type === 'video'),\n        hasGif: posts.some(p => p.embed.media?.type === 'gif'),\n        hasQuote: posts.some(p => !!p.embed.quote),\n        hasLink: posts.some(p => !!p.embed.link),\n        postCount: posts.length,\n        textLength: posts[0].richtext.text.length,\n      })\n\n      onClose()\n    } catch (e) {\n      logger.error('Failed to save draft', {error: e})\n      setError(getDraftSaveError(e))\n    }\n  }, [\n    saveDraft,\n    composerState,\n    composerDispatch,\n    onClose,\n    ax,\n    validateDraftTextOrError,\n    getDraftSaveError,\n  ])\n\n  // Save without closing - for use by DraftsButton\n  const saveCurrentDraft = useCallback(async (): Promise<{\n    success: boolean\n  }> => {\n    setError('')\n    if (!validateDraftTextOrError()) {\n      return {success: false}\n    }\n    try {\n      const result = await saveDraft({\n        composerState,\n        existingDraftId: composerState.draftId,\n      })\n      composerDispatch({type: 'mark_saved', draftId: result.draftId})\n      return {success: true}\n    } catch (e) {\n      setError(getDraftSaveError(e))\n      return {success: false}\n    }\n  }, [\n    saveDraft,\n    composerState,\n    composerDispatch,\n    validateDraftTextOrError,\n    getDraftSaveError,\n  ])\n\n  // Handle discard action - fires metric and closes composer\n  const handleDiscard = useCallback(() => {\n    const posts = thread.posts\n    const hasContent = posts.some(\n      post =>\n        post.richtext.text.trim().length > 0 ||\n        post.embed.media ||\n        post.embed.link,\n    )\n    ax.metric('draft:discard', {\n      logContext: 'ComposerClose',\n      hadContent: hasContent,\n      textLength: posts[0].richtext.text.length,\n    })\n    onClose()\n  }, [thread.posts, ax, onClose])\n\n  // Check if composer is empty (no content to save)\n  const isComposerEmpty = useMemo(() => {\n    // Has multiple posts means it's not empty\n    if (thread.posts.length > 1) return false\n\n    const firstPost = thread.posts[0]\n    // Has text\n    if (firstPost.richtext.text.trim().length > 0) return false\n    // Has media\n    if (firstPost.embed.media) return false\n    // Has quote\n    if (firstPost.embed.quote) return false\n    // Has link\n    if (firstPost.embed.link) return false\n\n    return true\n  }, [thread.posts])\n\n  // Clear the composer (discard current content)\n  const handleClearComposer = useCallback(() => {\n    composerDispatch({\n      type: 'clear',\n      initInteractionSettings: preferences?.postInteractionSettings,\n    })\n  }, [composerDispatch, preferences?.postInteractionSettings])\n\n  const insets = useSafeAreaInsets()\n  const viewStyles = useMemo(\n    () => ({\n      paddingTop: IS_ANDROID || IS_IPAD ? insets.top : 0,\n      paddingBottom: insets.bottom,\n    }),\n    [insets.top, insets.bottom],\n  )\n\n  const onPressCancel = useCallback(() => {\n    if (isSavingDraft) {\n      return\n    }\n    if (textInputRef.current?.maybeClosePopup()) {\n      return\n    }\n\n    const hasContent = thread.posts.some(\n      post =>\n        post.shortenedGraphemeLength > 0 || post.embed.media || post.embed.link,\n    )\n\n    // Show discard prompt if there's content AND either:\n    // - No draft is loaded (new composition)\n    // - Draft is loaded but has been modified\n    if (hasContent && (!composerState.draftId || composerState.isDirty)) {\n      closeAllDialogs()\n      Keyboard.dismiss()\n      discardPromptControl.open()\n    } else {\n      onClose()\n    }\n  }, [\n    isSavingDraft,\n    thread,\n    composerState.draftId,\n    composerState.isDirty,\n    closeAllDialogs,\n    discardPromptControl,\n    onClose,\n  ])\n\n  useImperativeHandle(cancelRef, () => ({onPressCancel}))\n\n  // On Android, pressing Back should ask confirmation.\n  useEffect(() => {\n    if (!IS_ANDROID) {\n      return\n    }\n    const backHandler = BackHandler.addEventListener(\n      'hardwareBackPress',\n      () => {\n        if (closeAllDialogs()) {\n          return true\n        }\n        onPressCancel()\n        return true\n      },\n    )\n    return () => {\n      backHandler.remove()\n    }\n  }, [onPressCancel, closeAllDialogs])\n\n  const missingAltError = useMemo(() => {\n    if (!requireAltTextEnabled) {\n      return\n    }\n    for (let i = 0; i < thread.posts.length; i++) {\n      const media = thread.posts[i].embed.media\n      if (media) {\n        if (\n          (media.type === 'images' || media.type === 'gallery') &&\n          media.images.some(img => !img.alt)\n        ) {\n          return l`One or more images is missing alt text.`\n        }\n        if (media.type === 'gif' && !media.alt) {\n          return l`One or more GIFs is missing alt text.`\n        }\n        if (\n          media.type === 'video' &&\n          media.video.status !== 'error' &&\n          !media.video.altText\n        ) {\n          return l`One or more videos is missing alt text.`\n        }\n      }\n    }\n  }, [thread, requireAltTextEnabled, l])\n\n  // Subscribe to the resolve-link cache for any link URIs in the thread so we\n  // can detect chat invites that resolved to no preview (revoked/expired) and\n  // block publishing - otherwise the post would go out without the embed.\n  const linkUris = thread.posts\n    .filter(post => post.embed.link)\n    .map(post => post.embed.link!.uri)\n  const linkQueries = useQueries({\n    queries: linkUris.map(uri => ({\n      ...resolveLinkQueryOptions({appviewClient: client, chatClient}, uri),\n      enabled: false,\n    })),\n  })\n  const hasUnavailableChatInvite = linkQueries.some(\n    q =>\n      q.data?.type === 'chat-invite' &&\n      !bsky.isType(chat.bsky.group.defs.joinLinkPreviewView, q.data.view),\n  )\n\n  const canPost =\n    !missingAltError &&\n    !hasUnavailableChatInvite &&\n    thread.posts.some(post => !isEmptyPost(post)) &&\n    thread.posts.every(\n      post =>\n        isEmptyPost(post) ||\n        (post.shortenedGraphemeLength <= MAX_GRAPHEME_LENGTH &&\n          !(\n            post.embed.media?.type === 'video' &&\n            post.embed.media.video.status === 'error'\n          )),\n    )\n\n  const getFilteredThread = useCallback((): {\n    type: 'none' | 'trailing-only' | 'non-trailing'\n    filteredThread: ThreadDraft\n  } => {\n    const nonEmptyPosts = thread.posts.filter(post => !isEmptyPost(post))\n\n    if (nonEmptyPosts.length === thread.posts.length) {\n      return {type: 'none', filteredThread: thread}\n    }\n\n    let lastNonEmptyIndex = -1\n    for (let i = thread.posts.length - 1; i >= 0; i--) {\n      if (!isEmptyPost(thread.posts[i])) {\n        lastNonEmptyIndex = i\n        break\n      }\n    }\n\n    const hasNonTrailingEmpty = thread.posts.some(\n      (post, i) => i < lastNonEmptyIndex && isEmptyPost(post),\n    )\n\n    const filteredThread: ThreadDraft = {...thread, posts: nonEmptyPosts}\n\n    return {\n      type: hasNonTrailingEmpty ? 'non-trailing' : 'trailing-only',\n      filteredThread,\n    }\n  }, [thread])\n\n  const onPressPublish = useCallback(async () => {\n    if (isPublishing || isSavingDraft) {\n      return\n    }\n\n    if (!canPost) {\n      return\n    }\n\n    const {type: emptyType, filteredThread} = getFilteredThread()\n\n    if (emptyType === 'non-trailing' && !skipEmptyConfirmedRef.current) {\n      emptyPostsPromptControl.open()\n      return\n    }\n\n    if (\n      filteredThread.posts.some(\n        post =>\n          post.embed.media?.type === 'video' &&\n          post.embed.media.video.asset &&\n          post.embed.media.video.status !== 'done',\n      )\n    ) {\n      setPublishOnUpload(true)\n      return\n    }\n\n    skipEmptyConfirmedRef.current = false\n    setError('')\n    setIsPublishing(true)\n\n    let postUri: string | undefined\n    let postSuccessData: OnPostSuccessData\n    try {\n      logger.info(`composer: posting...`)\n      postUri = (\n        await apilib.post(queryClient, {\n          thread: filteredThread,\n          replyTo: replyTo?.uri,\n          onStateChange: setPublishingStage,\n          langs: currentLanguages,\n          appviewClient: client,\n          chatClient,\n          pdsClient,\n        })\n      ).uris[0]\n\n      // Fire published event for every video that made it into the post.\n      // The status guard upstream ensures each video.telemetry is present and\n      // processing has completed by this point.\n      for (const post of filteredThread.posts) {\n        if (post.embed.media?.type === 'video') {\n          post.embed.media.video.telemetry?.published()\n        }\n      }\n\n      /*\n       * Wait for app view to have received the post(s). If this fails, it's\n       * ok, because the post _was_ actually published above.\n       */\n      try {\n        if (postUri) {\n          logger.info(`composer: waiting for app view`)\n\n          const posts = await retry(\n            5,\n            _e => true,\n            async () => {\n              const res = await client.call(\n                app.bsky.unspecced.getPostThreadV2,\n                {\n                  anchor: postUri! as AtUriString,\n                  above: false,\n                  below: filteredThread.posts.length - 1,\n                  branchingFactor: 1,\n                },\n              )\n              if (res.thread.length !== filteredThread.posts.length) {\n                throw new Error(`composer: app view is not ready`)\n              }\n              if (\n                !res.thread.every(p =>\n                  bsky.isType(app.bsky.unspecced.defs.threadItemPost, p.value),\n                )\n              ) {\n                throw new Error(`composer: app view returned non-post items`)\n              }\n              return res.thread\n            },\n            1e3,\n          )\n          postSuccessData = {\n            replyToUri: replyTo?.uri,\n            posts,\n          }\n        }\n      } catch (waitErr) {\n        logger.info(`composer: waiting for app view failed`, {\n          safeMessage: waitErr,\n        })\n      }\n    } catch (e) {\n      logger.error(e instanceof Error ? e : String(e), {\n        message: `Composer: create post failed`,\n        hasImages: filteredThread.posts.some(\n          p =>\n            p.embed.media?.type === 'images' ||\n            p.embed.media?.type === 'gallery',\n        ),\n      })\n\n      let err = e instanceof Error ? cleanError(e.message) : String(e)\n      if (\n        e instanceof apilib.ReplyDeletedError ||\n        err.includes('not locate record')\n      ) {\n        err = l`We're sorry! The post you are replying to has been deleted.`\n      } else if (e instanceof EmbeddingDisabledError) {\n        err = l`This post's author has disabled quote posts.`\n      }\n      setError(err)\n      setIsPublishing(false)\n      return\n    } finally {\n      if (postUri) {\n        let index = 0\n        for (let post of filteredThread.posts) {\n          ax.metric('post:create', {\n            imageCount:\n              post.embed.media?.type === 'images' ||\n              post.embed.media?.type === 'gallery'\n                ? post.embed.media.images.length\n                : 0,\n            isReply: index > 0 || !!replyTo,\n            isPartOfThread: filteredThread.posts.length > 1,\n            hasLink: !!post.embed.link,\n            hasQuote: !!post.embed.quote,\n            langs: fromPostLanguages(currentLanguages),\n            logContext: 'Composer',\n          })\n          index++\n        }\n      }\n      if (filteredThread.posts.length > 1) {\n        ax.metric('thread:create', {\n          postCount: filteredThread.posts.length,\n          isReply: !!replyTo,\n        })\n      }\n      if (postUri) {\n        for (const q of linkQueries) {\n          const resolved = q.data\n          if (\n            resolved?.type === 'chat-invite' &&\n            bsky.isType(chat.bsky.group.defs.joinLinkPreviewView, resolved.view)\n          ) {\n            ax.metric('groupchat:inviteLink:shared', {\n              convoId: resolved.view.convoId,\n              method: 'post',\n            })\n          }\n        }\n      }\n    }\n    if (postUri && !replyTo) {\n      emitPostCreated()\n    }\n    // Clean up draft and its media after successful publish\n    if (composerState.draftId && composerState.originalLocalRefs) {\n      // Fire draft:post metric\n      if (loadedDraftCreatedAt) {\n        const draftAgeMs = Date.now() - new Date(loadedDraftCreatedAt).getTime()\n        ax.metric('draft:post', {\n          draftAgeMs,\n          wasEdited: composerState.isDirty,\n        })\n      }\n\n      logger.debug('post published, cleaning up draft', {\n        draftId: composerState.draftId,\n        mediaFileCount: composerState.originalLocalRefs.size,\n      })\n      cleanupPublishedDraft({\n        draftId: composerState.draftId,\n        originalLocalRefs: composerState.originalLocalRefs,\n      })\n    }\n    setLangPrefs.savePostLanguageToHistory(fromPostLanguages(currentLanguages))\n    if (initQuote) {\n      // We want to wait for the quote count to update before we call `onPost`, which will refetch data\n      void whenAppViewReady(client, initQuote.uri, res => {\n        const anchor = res?.thread.at(0)\n        if (\n          bsky.isType(app.bsky.unspecced.defs.threadItemPost, anchor?.value) &&\n          anchor.value.post.quoteCount !== initQuote.quoteCount\n        ) {\n          onPost?.(postUri)\n          onPostSuccess?.(postSuccessData)\n          return true\n        }\n        return false\n      })\n    } else {\n      onPost?.(postUri)\n      onPostSuccess?.(postSuccessData)\n    }\n    onClose()\n    setTimeout(() => {\n      Toast.show(\n        <Toast.Outer>\n          <Toast.Icon />\n          <Toast.Text>\n            {filteredThread.posts.length > 1\n              ? l`Your posts were sent`\n              : replyTo\n                ? l`Your reply was sent`\n                : l`Your post was sent`}\n          </Toast.Text>\n          {postUri && (\n            <Toast.Action\n              label={l`View post`}\n              onPress={() => {\n                const {host: name, rkey} = new AtUri(postUri)\n                navigation.navigate('PostThread', {name, rkey})\n              }}>\n              <Trans context=\"Action to view the post the user just created\">\n                View\n              </Trans>\n            </Toast.Action>\n          )}\n        </Toast.Outer>,\n        {type: 'success'},\n      )\n    }, 500)\n  }, [\n    l,\n    ax,\n    client,\n    chatClient,\n    pdsClient,\n    canPost,\n    isPublishing,\n    isSavingDraft,\n    currentLanguages,\n    onClose,\n    onPost,\n    onPostSuccess,\n    initQuote,\n    replyTo,\n    setLangPrefs,\n    queryClient,\n    navigation,\n    composerState.draftId,\n    composerState.originalLocalRefs,\n    composerState.isDirty,\n    cleanupPublishedDraft,\n    loadedDraftCreatedAt,\n    emptyPostsPromptControl,\n    getFilteredThread,\n    linkQueries,\n  ])\n\n  const handleConfirmSkipEmpty = () => {\n    skipEmptyConfirmedRef.current = true\n    void onPressPublish()\n  }\n\n  // Preserves the referential identity passed to each post item.\n  // Avoids re-rendering all posts on each keystroke.\n  const onComposerPostPublish = useNonReactiveCallback(() => {\n    void onPressPublish()\n  })\n\n  useEffect(() => {\n    if (publishOnUpload) {\n      let erroredVideos = 0\n      let uploadingVideos = 0\n      for (let post of thread.posts) {\n        if (isEmptyPost(post)) continue\n        if (post.embed.media?.type === 'video') {\n          const video = post.embed.media.video\n          if (video.status === 'error') {\n            erroredVideos++\n          } else if (video.status !== 'done') {\n            uploadingVideos++\n          }\n        }\n      }\n      if (erroredVideos > 0) {\n        setPublishOnUpload(false)\n      } else if (uploadingVideos === 0) {\n        setPublishOnUpload(false)\n        void onPressPublish()\n      }\n    }\n  }, [thread.posts, onPressPublish, publishOnUpload])\n\n  // TODO: It might make more sense to display this error per-post.\n  // Right now we're just displaying the first one.\n  let erroredVideoPostId: string | undefined\n  let erroredVideo: VideoState | NoVideoState = NO_VIDEO\n  for (let i = 0; i < thread.posts.length; i++) {\n    const post = thread.posts[i]\n    if (\n      post.embed.media?.type === 'video' &&\n      post.embed.media.video.status === 'error'\n    ) {\n      erroredVideoPostId = post.id\n      erroredVideo = post.embed.media.video\n      break\n    }\n  }\n\n  const scrollViewRef = useAnimatedRef<Animated.ScrollView>()\n  useEffect(() => {\n    if (composerState.mutableNeedsFocusActive) {\n      composerState.mutableNeedsFocusActive = false\n      // On Android, this risks getting the cursor stuck behind the keyboard.\n      // Not worth it.\n      if (!IS_ANDROID) {\n        textInputRef.current?.focus()\n      }\n    }\n  }, [composerState])\n\n  useEffect(() => {\n    // Safari ignores `overscroll-behavior`, so horizontal trackpad swipes over\n    // the composer (e.g. on a quote post) can still trigger the browser's\n    // back/forward navigation gesture. Suppress predominantly-horizontal wheel\n    // events so the history-nav gesture never fires. Chrome and Firefox are\n    // covered by the `overscrollBehaviorX: 'contain'` style on the ScrollView.\n    if (!IS_WEB_SAFARI) return\n    const el =\n      scrollViewRef.current?.getScrollableNode() as unknown as HTMLElement | null\n    if (!el) return\n    const onWheel = (e: WheelEvent) => {\n      if (Math.abs(e.deltaX) <= Math.abs(e.deltaY)) return\n      e.preventDefault()\n    }\n    el.addEventListener('wheel', onWheel, {passive: false})\n    return () => el.removeEventListener('wheel', onWheel)\n  }, [scrollViewRef])\n\n  const isLastThreadedPost = thread.posts.length > 1 && nextPost === undefined\n  const {\n    scrollHandler,\n    onScrollViewContentSizeChange,\n    onScrollViewLayout,\n    topBarAnimatedStyle,\n    bottomBarAnimatedStyle,\n  } = useScrollTracker({\n    scrollViewRef,\n    stickyBottom: isLastThreadedPost,\n  })\n\n  const keyboardVerticalOffset = useKeyboardVerticalOffset()\n\n  const footer = (\n    <>\n      <SuggestedLanguage\n        text={activePost.richtext.text}\n        replyToLanguages={replyToLanguages}\n        currentLanguages={currentLanguages}\n        onAcceptSuggestedLanguage={setSelectedPostLanguage}\n        onNudge={onLanguageNudge}\n      />\n      <ComposerPills\n        isReply={!!replyTo}\n        post={activePost}\n        thread={composerState.thread}\n        dispatch={composerDispatch}\n        bottomBarAnimatedStyle={bottomBarAnimatedStyle}\n      />\n      <ComposerFooter\n        post={activePost}\n        dispatch={dispatch}\n        showAddButton={\n          !isEmptyPost(activePost) && (!nextPost || !isEmptyPost(nextPost))\n        }\n        onError={setError}\n        onSelectVideo={selectVideo}\n        onAddPost={() => {\n          composerDispatch({\n            type: 'add_post',\n          })\n        }}\n        currentLanguages={currentLanguages}\n        onSelectLanguage={onSelectLanguage}\n        languageNudgeAt={languageNudgeAt}\n        openGallery={openGallery}\n        textInputRef={textInputRef}\n      />\n    </>\n  )\n\n  const IS_WEBFooterSticky = !IS_NATIVE && thread.posts.length > 1\n  return (\n    <BottomSheetPortalProvider>\n      <KeyboardAvoidingView\n        testID=\"composePostView\"\n        behavior={IS_IOS ? 'padding' : 'height'}\n        keyboardVerticalOffset={keyboardVerticalOffset}\n        automaticOffset={IS_IPAD}\n        style={a.flex_1}>\n        <View\n          style={[a.flex_1, viewStyles]}\n          aria-modal\n          accessibilityViewIsModal>\n          <ComposerTopBar\n            canPost={canPost}\n            isReply={!!replyTo}\n            isPublishQueued={publishOnUpload}\n            isPublishing={isPublishing}\n            isSavingDraft={isSavingDraft}\n            isThread={thread.posts.length > 1}\n            publishingStage={publishingStage}\n            topBarAnimatedStyle={topBarAnimatedStyle}\n            onCancel={onPressCancel}\n            onPublish={() => void onPressPublish()}\n            onSelectDraft={draft => void handleSelectDraft(draft)}\n            onSaveDraft={saveCurrentDraft}\n            onDiscard={handleClearComposer}\n            isEmpty={isComposerEmpty}\n            isDirty={composerState.isDirty}\n            isEditingDraft={!!composerState.draftId}\n            canSaveDraft={allPostsWithinLimit}\n            textLength={thread.posts[0].richtext.text.length}>\n            {missingAltError && <AltTextReminder error={missingAltError} />}\n            <ErrorBanner\n              error={error}\n              videoState={erroredVideo}\n              clearError={() => setError('')}\n              clearVideo={\n                erroredVideoPostId\n                  ? () => clearVideo(erroredVideoPostId)\n                  : () => {}\n              }\n            />\n          </ComposerTopBar>\n\n          <Animated.ScrollView\n            ref={scrollViewRef}\n            onScroll={scrollHandler}\n            contentContainerStyle={a.flex_grow}\n            style={[\n              a.flex_1,\n              web({\n                scrollbarGutter: 'stable',\n                scrollbarColor: `${t.palette.contrast_200} transparent`,\n                // Prevent horizontal trackpad swipes from triggering the\n                // browser's back/forward overscroll-navigation gesture.\n                // Handles Chrome and Firefox; Safari is handled separately\n                // via a wheel listener since it ignores overscroll-behavior.\n                overscrollBehaviorX: 'contain',\n              }),\n            ]}\n            keyboardShouldPersistTaps=\"always\"\n            onContentSizeChange={onScrollViewContentSizeChange}\n            onLayout={onScrollViewLayout}>\n            {replyTo ? <ComposerReplyTo replyTo={replyTo} /> : undefined}\n            {thread.posts.map((post, index) => (\n              <Fragment key={post.id + (composerState.draftId ?? '')}>\n                <ComposerPost\n                  post={post}\n                  dispatch={composerDispatch}\n                  textInputRef={post.id === activePost.id ? textInputRef : null}\n                  isFirstPost={index === 0}\n                  isLastPost={index === thread.posts.length - 1}\n                  isPartOfThread={thread.posts.length > 1}\n                  isReply={index > 0 || !!replyTo}\n                  isActive={post.id === activePost.id}\n                  canRemovePost={thread.posts.length > 1}\n                  canRemoveQuote={index > 0 || !initQuote}\n                  onSelectVideo={selectVideo}\n                  onClearVideo={clearVideo}\n                  onPublish={onComposerPostPublish}\n                  onError={setError}\n                />\n                {IS_WEBFooterSticky && post.id === activePost.id && (\n                  <View style={styles.stickyFooterWeb}>{footer}</View>\n                )}\n              </Fragment>\n            ))}\n          </Animated.ScrollView>\n          {!IS_WEBFooterSticky && footer}\n        </View>\n\n        {replyTo ? (\n          <Prompt.Basic\n            control={discardPromptControl}\n            title={l`Discard draft?`}\n            description=\"\"\n            confirmButtonCta={l`Discard`}\n            confirmButtonColor=\"negative\"\n            onConfirm={handleDiscard}\n          />\n        ) : (\n          <Prompt.Outer control={discardPromptControl}>\n            <Prompt.Content>\n              <Prompt.TitleText>\n                {allPostsWithinLimit ? (\n                  composerState.draftId ? (\n                    <Trans>Save changes?</Trans>\n                  ) : (\n                    <Trans>Save draft?</Trans>\n                  )\n                ) : (\n                  <Trans>Discard post?</Trans>\n                )}\n              </Prompt.TitleText>\n              <Prompt.DescriptionText>\n                {allPostsWithinLimit ? (\n                  composerState.draftId ? (\n                    <Trans>\n                      You have unsaved changes to this draft, would you like to\n                      save them?\n                    </Trans>\n                  ) : (\n                    <Trans>\n                      Would you like to save this as a draft to edit later?\n                    </Trans>\n                  )\n                ) : (\n                  <Trans>You can only save drafts up to 1000 characters.</Trans>\n                )}\n              </Prompt.DescriptionText>\n            </Prompt.Content>\n            <Prompt.Actions>\n              {allPostsWithinLimit && (\n                <Prompt.Action\n                  cta={composerState.draftId ? l`Save changes` : l`Save draft`}\n                  onPress={() => void handleSaveDraft()}\n                  color=\"primary\"\n                />\n              )}\n              <Prompt.Cancel cta={l`Keep editing`} />\n              <Prompt.Action\n                cta={l`Discard`}\n                onPress={handleDiscard}\n                color=\"negative_subtle\"\n              />\n            </Prompt.Actions>\n          </Prompt.Outer>\n        )}\n\n        <Prompt.Basic\n          control={emptyPostsPromptControl}\n          title={l`Skip empty posts?`}\n          description={l`Your thread has empty posts that will be skipped. The remaining posts will be published as a thread.`}\n          confirmButtonCta={l`Post anyway`}\n          cancelButtonCta={l`Keep editing`}\n          onConfirm={handleConfirmSkipEmpty}\n        />\n      </KeyboardAvoidingView>\n    </BottomSheetPortalProvider>\n  )\n}","file":"src/view/com/composer/Composer.tsx","kind":"component","line":254,"members":{"allPostsWithinLimit":[428,430],"ax":[272,272],"cancelRef":[254,269],"chatClient":[274,274],"clearVideo":[554,565],"client":[273,273],"composerState":[361,371],"currentLanguages":[330,336],"discardPromptControl":[289,289],"dispatch":[435,444],"emptyPostsPromptControl":[290,290],"error":[301,301],"getDraftSaveError":[784,794],"getFilteredThread":[1048,1076],"handleClearComposer":[918,923],"handleConfirmSkipEmpty":[1341,1344],"handleDiscard":[883,897],"handleSaveDraft":[809,853],"handleSelectDraft":[711,769],"hasUnavailableChatInvite":[1028,1032],"initImageUris":[254,269],"initMention":[254,269],"initQuote":[254,269],"initQuoteUri":[254,269],"initText":[254,269],"initVideoUri":[254,269],"insets":[925,925],"isComposerEmpty":[900,915],"isPublishing":[299,299],"keyboardVerticalOffset":[1434,1434],"langPrefs":[286,286],"languageNudgeAt":[353,353],"linkQueries":[1022,1027],"linkUris":[1019,1021],"loadedDraftCreatedAt":[307,309],"logContext":[254,269],"missingAltError":[989,1014],"navigation":[297,297],"onClose":[773,782],"onComposerPostPublish":[1348,1350],"onInitVideo":[534,538],"onLanguageNudge":[354,359],"onPost":[254,269],"onPostSuccess":[254,269],"onPressCancel":[934,965],"onPressPublish":[1078,1339],"onSelectLanguage":[342,345],"openGallery":[254,269],"pdsClient":[275,275],"publishOnUpload":[771,771],"publishingStage":[300,300],"queryClient":[276,276],"replyTo":[254,269],"replyToLanguages":[322,324],"requireAltTextEnabled":[285,285],"restoreVideo":[567,709],"saveCurrentDraft":[856,880],"scrollViewRef":[1392,1392],"selectVideo":[446,532],"selectedPostLanguage":[315,317],"setLangPrefs":[287,287],"skipEmptyConfirmedRef":[291,291],"t":[271,271],"textInputRef":[288,288],"uncheckedQuoteUri":[380,382],"validateDraftTextOrError":[796,807],"viewStyles":[926,932]},"supers":[]},"Composer":{"alsoIn":["src/view/shell/Composer.ios.tsx","src/components/Composer/index.tsx","src/screens/Messages/components/MessagesList.tsx","src/view/shell/Composer.web.tsx"],"appearsIn":[["composer","h-classes","Logic \u00b7 class diagram"]],"code":"export function Composer() {\n  const state = useComposerState()\n  const t = useTheme()\n\n  const open = !!state\n\n  useEffect(() => {\n    if (open) {\n      const entry = StatusBar.pushStackEntry({\n        barStyle: t.name !== 'light' ? 'light-content' : 'dark-content',\n        animated: true,\n      })\n      return () => StatusBar.popStackEntry(entry)\n    }\n  }, [open, t.name])\n\n  if (!open) {\n    return null\n  }\n\n  return (\n    <Animated.View\n      style={[a.absolute, a.inset_0, t.atoms.bg]}\n      entering={SlideInDown.duration(300).easing(Easing.out(Easing.exp))}\n      exiting={SlideOutDown.duration(200).easing(Easing.in(Easing.quad))}\n      aria-modal\n      accessibilityViewIsModal>\n      <ComposePost\n        replyTo={state.replyTo}\n        onPost={state.onPost}\n        onPostSuccess={state.onPostSuccess}\n        quote={state.quote}\n        quoteUri={state.quoteUri}\n        mention={state.mention}\n        text={state.text}\n        imageUris={state.imageUris}\n        videoUri={state.videoUri}\n        openGallery={state.openGallery}\n      />\n    </Animated.View>\n  )\n}","file":"src/view/shell/Composer.tsx","kind":"component","line":13,"members":{"state":[14,14],"t":[15,15]},"supers":[]},"ComposerAction":{"appearsIn":[["composer","h-classes","Logic \u00b7 class diagram"]],"code":"export type ComposerAction =\n  | {type: 'update_postgate'; postgate: app.bsky.feed.postgate.Main}\n  | {type: 'update_threadgate'; threadgate: ThreadgateAllowUISetting[]}\n  | {\n      type: 'update_post'\n      postId: string\n      postAction: PostAction\n    }\n  | {\n      type: 'add_post'\n    }\n  | {\n      type: 'remove_post'\n      postId: string\n    }\n  | {\n      type: 'focus_post'\n      postId: string\n    }\n  | {\n      type: 'restore_from_draft'\n      draftId: string\n      posts: PostDraft[]\n      threadgateAllow: app.bsky.draft.defs.Draft['threadgateAllow']\n      postgateEmbeddingRules: app.bsky.draft.defs.Draft['postgateEmbeddingRules']\n\n      /** Map of localRefPath -> loaded media path/URL */\n      loadedMedia: Map<string, string>\n      /** Set of original localRef paths from the draft. Used to identify orphaned media on save. */\n      originalLocalRefs: Set<string>\n    }\n  | {\n      type: 'clear'\n      initInteractionSettings:\n        app.bsky.actor.defs.PostInteractionSettingsPref | undefined\n    }\n  | {\n      type: 'mark_saved'\n      draftId: string\n    }","file":"src/view/com/composer/state/composer.ts","kind":"type","line":126,"members":{},"supers":[]},"ComposerFooter":{"appearsIn":[["composer","h-widgets","Screen \u00b7 component composition"]],"code":"function ComposerFooter({\n  post,\n  dispatch,\n  showAddButton,\n  onSelectVideo,\n  onAddPost,\n  currentLanguages,\n  onSelectLanguage,\n  languageNudgeAt,\n  openGallery,\n  textInputRef,\n}: {\n  post: PostDraft\n  dispatch: (action: PostAction) => void\n  showAddButton: boolean\n  onError: (error: string) => void\n  onSelectVideo: (\n    postId: string,\n    asset: ImagePickerAsset,\n  ) => void | Promise<void>\n  onAddPost: () => void\n  currentLanguages: string[]\n  onSelectLanguage: (language: string) => void\n  languageNudgeAt: number\n  openGallery?: boolean\n  textInputRef: React.RefObject<TextInputRef | null>\n}) {\n  const t = useTheme()\n  const {t: l} = useLingui()\n  const {gtPhone} = useBreakpoints()\n  /*\n   * Once we've allowed a certain type of asset to be selected, we don't allow\n   * other types of media to be selected.\n   */\n  const [selectedAssetsType, setSelectedAssetsType] = useState<\n    AssetType | undefined\n  >(undefined)\n\n  const media = post.embed.media\n  const images =\n    media?.type === 'images' || media?.type === 'gallery' ? media.images : []\n  const video = media?.type === 'video' ? media.video : null\n  const isMaxImages = images.length >= MAX_GALLERY_IMAGES\n  const isMaxVideos = !!video\n\n  let selectedAssetsCount = 0\n  let isMediaSelectionDisabled = false\n\n  if (media?.type === 'images' || media?.type === 'gallery') {\n    isMediaSelectionDisabled = isMaxImages\n    selectedAssetsCount = images.length\n  } else if (media?.type === 'video') {\n    isMediaSelectionDisabled = isMaxVideos\n    selectedAssetsCount = 1\n  } else {\n    isMediaSelectionDisabled = !!media\n  }\n\n  const onImageAdd = useAddImagesWithCap(images.length, dispatch)\n\n  const onSelectGif = useCallback(\n    (gif: Gif) => {\n      dispatch({type: 'embed_add_gif', gif})\n    },\n    [dispatch],\n  )\n\n  /*\n   * Reset if the user clears any selected media\n   */\n  if (selectedAssetsType !== undefined && !media) {\n    setSelectedAssetsType(undefined)\n  }\n\n  const onSelectAssets = useCallback<SelectMediaButtonProps['onSelectAssets']>(\n    async ({type, assets, errors}) => {\n      setSelectedAssetsType(type)\n\n      if (assets.length) {\n        if (type === 'image') {\n          const selectedImages: ComposerImage[] = []\n\n          await Promise.all(\n            assets.map(async image => {\n              const composerImage = await createComposerImage({\n                path: image.uri,\n                width: image.width,\n                height: image.height,\n                mime: image.mimeType!,\n              })\n              selectedImages.push(composerImage)\n            }),\n          ).catch(e => {\n            logger.error(`createComposerImage failed`, {\n              safeMessage: e instanceof Error ? e.message : String(e),\n            })\n          })\n\n          onImageAdd(selectedImages)\n        } else if (type === 'video') {\n          void onSelectVideo(post.id, assets[0])\n        } else if (type === 'gif') {\n          void onSelectVideo(post.id, assets[0])\n        }\n      }\n\n      errors.map(error => {\n        Toast.show(error, {\n          type: 'warning',\n        })\n      })\n    },\n    [post.id, onSelectVideo, onImageAdd],\n  )\n\n  return (\n    <View\n      style={[\n        a.flex_row,\n        a.py_xs,\n        {paddingLeft: 7, paddingRight: 16},\n        a.align_center,\n        a.border_t,\n        t.atoms.bg,\n        t.atoms.border_contrast_medium,\n        a.justify_between,\n      ]}>\n      <View style={[a.flex_row, a.align_center]}>\n        <LayoutAnimationConfig skipEntering skipExiting>\n          {video && video.status !== 'done' ? (\n            <VideoUploadToolbar state={video} />\n          ) : (\n            <ToolbarWrapper style={[a.flex_row, a.align_center, a.gap_xs]}>\n              <SelectMediaButton\n                disabled={isMediaSelectionDisabled}\n                allowedAssetTypes={selectedAssetsType}\n                selectedAssetsCount={selectedAssetsCount}\n                onSelectAssets={onSelectAssets}\n                autoOpen={openGallery}\n              />\n              <OpenCameraBtn\n                disabled={\n                  media?.type === 'images' || media?.type === 'gallery'\n                    ? isMaxImages\n                    : !!media\n                }\n                onAdd={onImageAdd}\n              />\n              <SelectGifBtn onSelectGif={onSelectGif} disabled={!!media} />\n              {IS_WEB && gtPhone ? (\n                <EmojiPicker.Root nextFocusRef={textInputRef}>\n                  <EmojiPicker.Trigger label={l`Open emoji picker`}>\n                    {({props}) => (\n                      <Button\n                        style={a.p_sm}\n                        label={props.accessibilityLabel}\n                        variant=\"ghost\"\n                        shape=\"round\"\n                        color=\"primary\"\n                        {...props}>\n                        <EmojiSmileIcon size=\"lg\" />\n                      </Button>\n                    )}\n                  </EmojiPicker.Trigger>\n                  <EmojiPicker.Picker />\n                </EmojiPicker.Root>\n              ) : null}\n            </ToolbarWrapper>\n          )}\n        </LayoutAnimationConfig>\n      </View>\n      <View style={[a.flex_row, a.align_center, a.justify_between]}>\n        {showAddButton && (\n          <Button\n            label={l`Add another post to thread`}\n            onPress={onAddPost}\n            style={[a.p_sm]}\n            variant=\"ghost\"\n            shape=\"round\"\n            color=\"primary\">\n            <PlusIcon size=\"lg\" />\n          </Button>\n        )}\n        <PostLanguageSelect\n          currentLanguages={currentLanguages}\n          onSelectLanguage={onSelectLanguage}\n          nudgeAt={languageNudgeAt}\n        />\n        <CharProgress\n          count={post.shortenedGraphemeLength}\n          style={{width: 65}}\n        />\n      </View>\n    </View>\n  )\n}","file":"src/view/com/composer/Composer.tsx","kind":"component","line":2180,"members":{"currentLanguages":[2180,2206],"dispatch":[2180,2206],"languageNudgeAt":[2180,2206],"onAddPost":[2180,2206],"onImageAdd":[2238,2238],"onSelectAssets":[2254,2293],"onSelectGif":[2240,2245],"onSelectLanguage":[2180,2206],"onSelectVideo":[2180,2206],"openGallery":[2180,2206],"post":[2180,2206],"selectedAssetsType":[2214,2216],"showAddButton":[2180,2206],"t":[2207,2207],"textInputRef":[2180,2206]},"supers":[]},"ComposerPills":{"appearsIn":[["composer","h-widgets","Screen \u00b7 component composition"]],"code":"function ComposerPills({\n  isReply,\n  thread,\n  post,\n  dispatch,\n  bottomBarAnimatedStyle,\n}: {\n  isReply: boolean\n  thread: ThreadDraft\n  post: PostDraft\n  dispatch: (action: ComposerAction) => void\n  bottomBarAnimatedStyle: AnimatedStyle<ViewStyle>\n}) {\n  const t = useTheme()\n  const media = post.embed.media\n  const hasMedia =\n    media?.type === 'images' ||\n    media?.type === 'gallery' ||\n    media?.type === 'gif' ||\n    media?.type === 'video'\n  const hasLink = !!post.embed.link\n\n  // Don't render anything if no pills are going to be displayed\n  if (isReply && !hasMedia && !hasLink) {\n    return null\n  }\n\n  return (\n    <Animated.View\n      style={[a.flex_row, a.p_sm, t.atoms.bg, bottomBarAnimatedStyle]}>\n      <ScrollView\n        contentContainerStyle={[a.gap_sm]}\n        horizontal={true}\n        bounces={false}\n        keyboardShouldPersistTaps=\"always\"\n        showsHorizontalScrollIndicator={false}>\n        {isReply ? null : (\n          <ThreadgateBtn\n            postgate={thread.postgate}\n            onChangePostgate={nextPostgate => {\n              dispatch({type: 'update_postgate', postgate: nextPostgate})\n            }}\n            threadgateAllowUISettings={thread.threadgate}\n            onChangeThreadgateAllowUISettings={nextThreadgate => {\n              dispatch({\n                type: 'update_threadgate',\n                threadgate: nextThreadgate,\n              })\n            }}\n            style={bottomBarAnimatedStyle}\n          />\n        )}\n        {hasMedia || hasLink ? (\n          <LabelsBtn\n            labels={post.labels}\n            onChange={nextLabels => {\n              dispatch({\n                type: 'update_post',\n                postId: post.id,\n                postAction: {\n                  type: 'update_labels',\n                  labels: nextLabels,\n                },\n              })\n            }}\n          />\n        ) : null}\n      </ScrollView>\n    </Animated.View>\n  )\n}","file":"src/view/com/composer/Composer.tsx","kind":"component","line":2108,"members":{"bottomBarAnimatedStyle":[2108,2120],"dispatch":[2108,2120],"isReply":[2108,2120],"post":[2108,2120],"t":[2121,2121],"thread":[2108,2120]},"supers":[]},"ComposerPost":{"appearsIn":[["composer","h-widgets","Screen \u00b7 component composition"]],"code":"let ComposerPost = memo(function ComposerPost({\n  post,\n  dispatch,\n  textInputRef,\n  isActive,\n  isReply,\n  isFirstPost,\n  isLastPost,\n  isPartOfThread,\n  canRemovePost,\n  canRemoveQuote,\n  onClearVideo,\n  onSelectVideo,\n  onError,\n  onPublish,\n}: {\n  post: PostDraft\n  dispatch: (action: ComposerAction) => void\n  textInputRef: React.RefObject<TextInputRef | null> | null\n  isActive: boolean\n  isReply: boolean\n  isFirstPost: boolean\n  isLastPost: boolean\n  isPartOfThread: boolean\n  canRemovePost: boolean\n  canRemoveQuote: boolean\n  onClearVideo: (postId: string) => void\n  onSelectVideo: (\n    postId: string,\n    asset: ImagePickerAsset,\n  ) => void | Promise<void>\n  onError: (error: string) => void\n  onPublish: (richtext: RichText) => void\n}) {\n  const {currentAccount} = useSession()\n  const currentDid = currentAccount!.did\n  const {t: l} = useLingui()\n  const {data: currentProfile} = useProfileQuery({did: currentDid})\n  const richtext = post.richtext\n  const isTextOnly = !post.embed.link && !post.embed.quote && !post.embed.media\n  const forceMinHeight = IS_WEB && isTextOnly && isActive\n  const selectTextInputPlaceholder = isReply\n    ? isFirstPost\n      ? l`Write your reply`\n      : l`Add another post`\n    : l`What's up?`\n  const discardPromptControl = Prompt.usePromptControl()\n\n  const dispatchPost = useCallback(\n    (action: PostAction) => {\n      dispatch({\n        type: 'update_post',\n        postId: post.id,\n        postAction: action,\n      })\n    },\n    [dispatch, post.id],\n  )\n\n  const postImagesCount =\n    post.embed.media?.type === 'images' || post.embed.media?.type === 'gallery'\n      ? post.embed.media.images.length\n      : 0\n  const onImageAdd = useAddImagesWithCap(postImagesCount, dispatchPost)\n\n  const onNewLink = useCallback(\n    (uri: string) => {\n      dispatchPost({type: 'embed_add_uri', uri: uri as UriString})\n    },\n    [dispatchPost],\n  )\n\n  const onPhotoPasted = useCallback(\n    async (uri: string) => {\n      if (\n        uri.startsWith('data:video/') ||\n        (IS_WEB && uri.startsWith('data:image/gif'))\n      ) {\n        if (IS_NATIVE) return // web only\n        const [mimeType] = uri.slice('data:'.length).split(';')\n        if (!SUPPORTED_MIME_TYPES.includes(mimeType as SupportedMimeTypes)) {\n          Toast.show(l`Unsupported video type: ${mimeType}`, {\n            type: 'error',\n          })\n          return\n        }\n        const name = `pasted.${mimeToExt(mimeType)}`\n        const file = await fetch(uri)\n          .then(res => res.blob())\n          .then(blob => new File([blob], name, {type: mimeType}))\n        void onSelectVideo(post.id, await getVideoMetadata(file))\n      } else {\n        const res = await pasteImage(uri)\n        onImageAdd([res])\n      }\n    },\n    [post.id, onSelectVideo, onImageAdd, l],\n  )\n\n  useHideKeyboardOnBackground()\n\n  return (\n    <View\n      // Keep focused inputs attached while active-state opacity changes.\n      collapsable={false}\n      style={[\n        a.mx_lg,\n        a.mb_sm,\n        !isActive && isLastPost && a.mb_lg,\n        !isActive && styles.inactivePost,\n        isTextOnly && isLastPost && IS_NATIVE && a.flex_grow,\n      ]}>\n      <View style={[a.flex_row, IS_NATIVE && a.flex_1]}>\n        <UserAvatar\n          avatar={currentProfile?.avatar}\n          size={42}\n          type={currentProfile?.associated?.labeler ? 'labeler' : 'user'}\n          style={[a.mt_xs]}\n        />\n        <TextInput\n          ref={textInputRef}\n          style={[a.pt_xs]}\n          richtext={richtext}\n          placeholder={selectTextInputPlaceholder}\n          autoFocus={isActive}\n          webForceMinHeight={forceMinHeight}\n          // To avoid overlap with the close button:\n          hasRightPadding={isPartOfThread}\n          isActive={isActive}\n          setRichText={rt => {\n            dispatchPost({type: 'update_richtext', richtext: rt})\n          }}\n          onFocus={() => {\n            dispatch({\n              type: 'focus_post',\n              postId: post.id,\n            })\n          }}\n          onPhotoPasted={uri => void onPhotoPasted(uri)}\n          onNewLink={onNewLink}\n          onError={onError}\n          onPressPublish={onPublish}\n          accessible={true}\n          accessibilityLabel={l`Write post`}\n          accessibilityHint={l`Compose posts up to ${plural(\n            MAX_GRAPHEME_LENGTH || 0,\n            {\n              other: '# characters',\n            },\n          )} in length`}\n        />\n      </View>\n\n      {canRemovePost && isActive && (\n        <>\n          <Button\n            label={l`Delete post`}\n            size=\"small\"\n            color=\"secondary\"\n            variant=\"ghost\"\n            shape=\"round\"\n            style={[a.absolute, {top: 0, right: 0}]}\n            onPress={() => {\n              if (\n                post.shortenedGraphemeLength > 0 ||\n                post.embed.media ||\n                post.embed.link ||\n                post.embed.quote\n              ) {\n                discardPromptControl.open()\n              } else {\n                dispatch({\n                  type: 'remove_post',\n                  postId: post.id,\n                })\n              }\n            }}>\n            <ButtonIcon icon={XIcon} />\n          </Button>\n          <Prompt.Basic\n            control={discardPromptControl}\n            title={l`Discard post?`}\n            description={l`Are you sure you'd like to discard this post?`}\n            onConfirm={() => {\n              dispatch({\n                type: 'remove_post',\n                postId: post.id,\n              })\n            }}\n            confirmButtonCta={l`Discard`}\n            confirmButtonColor=\"negative\"\n          />\n        </>\n      )}\n\n      <ComposerEmbeds\n        canRemoveQuote={canRemoveQuote}\n        embed={post.embed}\n        dispatch={dispatchPost}\n        clearVideo={() => onClearVideo(post.id)}\n        isActivePost={isActive}\n      />\n    </View>\n  )\n})","file":"src/view/com/composer/Composer.tsx","kind":"component","line":1637,"members":{"canRemovePost":[1637,1670],"canRemoveQuote":[1637,1670],"discardPromptControl":[1683,1683],"dispatch":[1637,1670],"dispatchPost":[1685,1694],"isActive":[1637,1670],"isFirstPost":[1637,1670],"isLastPost":[1637,1670],"isPartOfThread":[1637,1670],"isReply":[1637,1670],"onClearVideo":[1637,1670],"onError":[1637,1670],"onImageAdd":[1700,1700],"onNewLink":[1702,1707],"onPhotoPasted":[1709,1734],"onPublish":[1637,1670],"onSelectVideo":[1637,1670],"post":[1637,1670],"textInputRef":[1637,1670]},"supers":[]},"ComposerReplyTo":{"appearsIn":[["composer","h-widgets","Screen \u00b7 component composition"]],"code":"export function ComposerReplyTo({replyTo}: {replyTo: ComposerOptsPostRef}) {\n  const t = useTheme()\n  const {_} = useLingui()\n  const {embed} = replyTo\n  const pronouns = replyTo.moderation?.ui('profileView').blur\n    ? undefined\n    : replyTo.author.pronouns?.trim()\n\n  const [showFull, setShowFull] = useState(false)\n\n  const onPress = useCallback(() => {\n    setShowFull(prev => !prev)\n    LayoutAnimation.configureNext({\n      duration: 350,\n      update: {type: 'spring', springDamping: 0.7},\n    })\n  }, [])\n\n  const quoteEmbed = useMemo(() => {\n    if (\n      bsky.isType(app.bsky.embed.record.view, embed) &&\n      bsky.isType(app.bsky.embed.record.viewRecord, embed.record) &&\n      bsky.isType(app.bsky.feed.post, embed.record.value)\n    ) {\n      return embed\n    } else if (\n      bsky.isType(app.bsky.embed.recordWithMedia.view, embed) &&\n      bsky.isType(app.bsky.embed.record.viewRecord, embed.record.record) &&\n      bsky.isType(app.bsky.feed.post, embed.record.record.value)\n    ) {\n      return embed.record\n    }\n    return null\n  }, [embed])\n  const parsedQuoteEmbed = quoteEmbed\n    ? parseEmbed({\n        $type: 'app.bsky.embed.record#view',\n        ...quoteEmbed,\n      })\n    : null\n\n  const {images, totalNumber} = useMemo(() => {\n    if (bsky.isType(app.bsky.embed.images.view, embed)) {\n      return {images: embed.images, totalNumber: embed.images.length}\n    } else if (bsky.isType(app.bsky.embed.gallery.view, embed)) {\n      return {\n        images: galleryItemsToImages(embed.items),\n        totalNumber: embed.items.length,\n      }\n    } else if (bsky.isType(app.bsky.embed.recordWithMedia.view, embed)) {\n      if (bsky.isType(app.bsky.embed.images.view, embed.media)) {\n        return {\n          images: embed.media.images,\n          totalNumber: embed.media.images.length,\n        }\n      } else if (bsky.isType(app.bsky.embed.gallery.view, embed.media)) {\n        return {\n          images: galleryItemsToImages(embed.media.items),\n          totalNumber: embed.media.items.length,\n        }\n      }\n    }\n    return {images: [], totalNumber: 0}\n  }, [embed])\n\n  return (\n    <Pressable\n      style={[\n        a.flex_row,\n        a.align_start,\n        a.pt_xs,\n        a.pb_lg,\n        a.mb_md,\n        a.mx_lg,\n        a.border_b,\n        t.atoms.border_contrast_medium,\n        web(a.user_select_text),\n      ]}\n      onPress={onPress}\n      accessibilityRole=\"button\"\n      accessibilityLabel={_(\n        msg`Expand or collapse the full post you are replying to`,\n      )}\n      accessibilityHint=\"\">\n      <PreviewableUserAvatar\n        size={42}\n        profile={replyTo.author}\n        moderation={replyTo.moderation?.ui('avatar')}\n        type={replyTo.author.associated?.labeler ? 'labeler' : 'user'}\n        disableNavigation={true}\n      />\n      <View style={[a.flex_1, a.pl_md, a.pr_sm, a.gap_2xs]}>\n        <View style={[a.flex_row, a.align_center, a.pr_xs]}>\n          <Text\n            style={[a.font_semi_bold, a.text_md, a.leading_snug, a.flex_shrink]}\n            numberOfLines={1}\n            emoji>\n            {sanitizeDisplayName(\n              replyTo.author.displayName ||\n                sanitizeHandle(replyTo.author.handle),\n            )}\n          </Text>\n          <ProfileBadges profile={replyTo.author} size=\"sm\" style={[a.pl_xs]} />\n          {pronouns && (\n            // the display name truncates first so pronouns stay whole\n            <Text\n              emoji\n              numberOfLines={1}\n              testID=\"composerReplyToPronouns\"\n              style={[\n                {paddingLeft: 10},\n                a.flex_shrink_0,\n                a.text_md,\n                a.leading_snug,\n                // matches the profile header's handle row\n                {color: t.palette.contrast_600},\n                web({unicodeBidi: 'isolate'}),\n              ]}>\n              {pronouns}\n            </Text>\n          )}\n        </View>\n        <View style={[a.flex_row, a.gap_md]}>\n          <View style={[a.flex_1, a.flex_grow]}>\n            <Text\n              style={[a.text_md, a.leading_snug, t.atoms.text_contrast_high]}\n              numberOfLines={!showFull ? 6 : undefined}\n              emoji>\n              {replyTo.text}\n            </Text>\n          </View>\n          {images && !replyTo.moderation?.ui('contentMedia').blur && (\n            <ComposerReplyToImages images={images} totalNumber={totalNumber} />\n          )}\n        </View>\n        {showFull && parsedQuoteEmbed && parsedQuoteEmbed.type === 'post' && (\n          <QuoteEmbed embed={parsedQuoteEmbed} linkDisabled />\n        )}\n      </View>\n    </Pressable>\n  )\n}","file":"src/view/com/composer/ComposerReplyTo.tsx","kind":"component","line":20,"members":{"onPress":[30,36],"quoteEmbed":[38,53],"replyTo":[20,20],"showFull":[28,28],"t":[21,21]},"supers":[]},"ComposerTopBar":{"appearsIn":[["composer","h-widgets","Screen \u00b7 component composition"]],"code":"function ComposerTopBar({\n  canPost,\n  isReply,\n  isPublishQueued,\n  isPublishing,\n  isSavingDraft,\n  isThread,\n  publishingStage,\n  onCancel,\n  onPublish,\n  onSelectDraft,\n  onSaveDraft,\n  onDiscard,\n  isEmpty,\n  isDirty,\n  isEditingDraft,\n  canSaveDraft,\n  textLength,\n  topBarAnimatedStyle,\n  children,\n}: {\n  isPublishing: boolean\n  isSavingDraft: boolean\n  publishingStage: string\n  canPost: boolean\n  isReply: boolean\n  isPublishQueued: boolean\n  isThread: boolean\n  onCancel: () => void\n  onPublish: () => void\n  onSelectDraft: (draft: DraftSummary) => void\n  onSaveDraft: () => Promise<{success: boolean}>\n  onDiscard: () => void\n  isEmpty: boolean\n  isDirty: boolean\n  isEditingDraft: boolean\n  canSaveDraft: boolean\n  textLength: number\n  topBarAnimatedStyle: AnimatedStyle<ViewStyle>\n  children?: React.ReactNode\n}) {\n  const t = useTheme()\n  const {t: l} = useLingui()\n\n  return (\n    <Animated.View style={topBarAnimatedStyle}>\n      <View\n        style={[\n          a.flex_row,\n          a.align_center,\n          a.gap_xs,\n          IS_LIQUID_GLASS ? [a.px_lg, a.pt_lg, a.pb_md] : [a.p_sm],\n        ]}>\n        <Button\n          label={l`Cancel`}\n          variant=\"ghost\"\n          color=\"primary\"\n          shape=\"default\"\n          size=\"small\"\n          style={[{paddingLeft: 7, paddingRight: 7}]}\n          hoverStyle={[a.bg_transparent, {opacity: 0.5}]}\n          onPress={onCancel}\n          disabled={isSavingDraft}\n          accessibilityHint={l`Closes post composer and discards post draft`}>\n          <ButtonText style={[a.text_md]} maxFontSizeMultiplier={2}>\n            <Trans>Cancel</Trans>\n          </ButtonText>\n        </Button>\n        <View style={a.flex_1} />\n        {isPublishing ? (\n          <>\n            <Text style={[t.atoms.text_contrast_medium]}>\n              {publishingStage}\n            </Text>\n            <View style={styles.postBtn}>\n              <ActivityIndicator />\n            </View>\n          </>\n        ) : (\n          <>\n            {!isReply && (\n              <DraftsButton\n                onSelectDraft={onSelectDraft}\n                onSaveDraft={onSaveDraft}\n                onDiscard={onDiscard}\n                isEmpty={isEmpty}\n                isDirty={isDirty}\n                isEditingDraft={isEditingDraft}\n                isSaving={isSavingDraft}\n                canSaveDraft={canSaveDraft}\n                textLength={textLength}\n              />\n            )}\n            <Button\n              testID=\"composerPublishBtn\"\n              label={\n                isReply\n                  ? isThread\n                    ? l({\n                        message: 'Publish replies',\n                        comment:\n                          'Accessibility label for button to publish multiple replies in a thread',\n                      })\n                    : l({\n                        message: 'Publish reply',\n                        comment:\n                          'Accessibility label for button to publish a single reply',\n                      })\n                  : isThread\n                    ? l({\n                        message: 'Publish posts',\n                        comment:\n                          'Accessibility label for button to publish multiple posts in a thread',\n                      })\n                    : l({\n                        message: 'Publish post',\n                        comment:\n                          'Accessibility label for button to publish a single post',\n                      })\n              }\n              color=\"primary\"\n              size=\"small\"\n              onPress={onPublish}\n              disabled={!canPost || isPublishQueued || isSavingDraft}>\n              <ButtonText style={[a.text_md]} maxFontSizeMultiplier={2}>\n                {isReply ? (\n                  <Trans context=\"action\">Reply</Trans>\n                ) : isThread ? (\n                  <Trans context=\"action\">Post All</Trans>\n                ) : (\n                  <Trans context=\"action\">Post</Trans>\n                )}\n              </ButtonText>\n            </Button>\n          </>\n        )}\n      </View>\n      {children}\n    </Animated.View>\n  )\n}","file":"src/view/com/composer/Composer.tsx","kind":"component","line":1843,"members":{"canPost":[1843,1883],"canSaveDraft":[1843,1883],"children":[1843,1883],"isDirty":[1843,1883],"isEditingDraft":[1843,1883],"isEmpty":[1843,1883],"isPublishQueued":[1843,1883],"isPublishing":[1843,1883],"isReply":[1843,1883],"isSavingDraft":[1843,1883],"isThread":[1843,1883],"onCancel":[1843,1883],"onDiscard":[1843,1883],"onPublish":[1843,1883],"onSaveDraft":[1843,1883],"onSelectDraft":[1843,1883],"publishingStage":[1843,1883],"t":[1884,1884],"textLength":[1843,1883],"topBarAnimatedStyle":[1843,1883]},"supers":[]},"SessionStateContext":{"appearsIn":[["composer","h-classes","Logic \u00b7 class diagram"],["launch","h-classes","Logic \u00b7 class diagram"],["sign-in","h-classes","Logic \u00b7 class diagram"]],"code":"export type SessionStateContext = {\n  accounts: SessionAccount[]\n  currentAccount: SessionAccount | undefined\n  hasSession: boolean\n}","file":"src/state/session/types.ts","kind":"type","line":9,"members":{"accounts":[10,10],"currentAccount":[11,11],"hasSession":[12,12]},"shot":"shots/code/SessionStateContext.jpg","supers":[]},"SuggestedLanguage":{"appearsIn":[["composer","h-widgets","Screen \u00b7 component composition"]],"code":"export function SuggestedLanguage({\n  text,\n  replyToLanguages: replyToLanguagesProp,\n  currentLanguages,\n  onAcceptSuggestedLanguage,\n  onNudge,\n}: {\n  text: string\n  /**\n   * All languages associated with the post being replied to.\n   */\n  replyToLanguages: string[]\n  /**\n   * All languages currently selected for the post being composed.\n   */\n  currentLanguages: string[]\n  /**\n   * Called when the user accepts a suggested language. We only pass a single\n   * language here. If the post being replied to has multiple languages, we\n   * only suggest the first one.\n   */\n  onAcceptSuggestedLanguage: (language: string | null) => void\n  /**\n   * Fired when detection produced ambiguous results \u2014 no strong suggestion\n   * to show, but we want to hint to the user that the detector is unsure.\n   * Expected to be an incrementing counter setter on the parent so the\n   * nudge can re-fire on each detection cycle.\n   */\n  onNudge?: () => void\n}) {\n  const ax = useAnalytics()\n  const [hasInteracted, setHasInteracted] = useState(false)\n  const [suggLang, setSuggLang] = useState<string | undefined>(undefined)\n  const declinedSuggLangsRef = useRef<string[]>([])\n\n  /*\n   * Shared callbacks\n   */\n  const onAccept = (language: string) => {\n    onAcceptSuggestedLanguage(language)\n    // clear\n    setSuggLang(undefined)\n  }\n  const onDecline = (language: string) => {\n    declinedSuggLangsRef.current.push(language)\n    // clear\n    setSuggLang(undefined)\n    setHasInteracted(true)\n  }\n\n  /**\n   * Merge in remote config (eventually)\n   */\n  const config = useMemo(() => DEFAULT_CONFIG, [])\n\n  /**\n   * Create non-reactive ref for debounced detection method.\n   */\n  const detectionPropsRef = useNonReactiveObject({\n    config,\n    currentLanguages,\n  })\n\n  /*\n   * Held in a ref so the debounced detection closure always sees the\n   * latest callback identity without rebuilding the debounce timer.\n   */\n  const handleOnNudge = useNonReactiveCallback(onNudge)\n\n  /*\n   * Main language detection effect\n   */\n  const detectLanguage = useMemo(() => {\n    return debounce(async (text: string) => {\n      try {\n        const currLangs = detectionPropsRef.current.currentLanguages\n        const {certain, uncertain} = await guessLanguage(\n          text,\n          detectionPropsRef.current.config,\n        )\n        const topCandidate = certain.at(0)?.language\n        if (\n          certain.length === 1 &&\n          uncertain.length === 0 &&\n          topCandidate !== undefined &&\n          !currLangs.includes(topCandidate) &&\n          !declinedSuggLangsRef.current.includes(topCandidate)\n        ) {\n          // we have a single confident candidate with no competitors \u2014 show it!\n          setSuggLang(topCandidate)\n        } else {\n          const nextBestCandidate = uncertain.at(0)?.language\n          // ambiguous results \u2014 if the top candidate isn't already\n          // selected or previously declined, nudge the user\n          if (\n            nextBestCandidate !== undefined &&\n            !currLangs.includes(nextBestCandidate) &&\n            !declinedSuggLangsRef.current.includes(nextBestCandidate)\n          ) {\n            handleOnNudge()\n            ax.metric('composer:language:nudgeUser', {\n              os: Platform.OS,\n              suggestedLanguage: nextBestCandidate,\n              currentTargetLanguages: currLangs,\n              textLength: text.length,\n            })\n          }\n\n          setSuggLang(undefined)\n        }\n      } catch (e) {\n        ax.logger.error('Error detecting language', {safeMessage: e})\n      }\n    }, 500)\n  }, [])\n\n  useEffect(() => {\n    // show reply prompt if there's not enough text to start using the model\n    if (text.length > 0 && !hasInteracted) {\n      setHasInteracted(true)\n    }\n\n    if (ax.features.enabled(ax.features.ComposerLanguageDetectionEnable)) {\n      const textTrimmed = sanitizeTextForDetection(text)\n\n      /*\n       * If text drops under the min length requirement, reset suggestions state\n       * objects.\n       *\n       * And we don't run the language model on small posts, the results are\n       * likely to be inaccurate.\n       */\n      if (textTrimmed.length < MIN_TEXT_LENGTH) {\n        setSuggLang(undefined)\n        return\n      }\n\n      void detectLanguage(textTrimmed)\n    }\n\n    // Cancel any pending debounced invocation on unmount / re-run so we\n    // don't call setSuggLang after the composer has closed (or after the\n    // user has already accepted a language).\n    return () => {\n      detectLanguage.cancel()\n    }\n  }, [text, hasInteracted, detectLanguage, ax])\n\n  /*\n   * We've detected a language, and the user hasn't already selected it.\n   * Note: suggLang is only set if it's not in declinedSuggLangsRef (checked\n   * in detectLanguage), so we don't need to filter it here.\n   */\n  const hasLanguageSuggestion = suggLang && !currentLanguages.includes(suggLang)\n\n  /*\n   * We have not detected a different language, and the user is not already\n   * using or has not already selected one of the languages of the post they\n   * are replying to.\n   */\n  const replyToLanguages = replyToLanguagesProp\n    .filter(Boolean)\n    .map(lang => parseLanguageString(lang)?.language)\n    .filter(Boolean) as string[]\n  const [replyToLanguage] = replyToLanguages\n  const hasSuggestedReplyLanguage =\n    !hasInteracted &&\n    !suggLang &&\n    replyToLanguage &&\n    !currentLanguages.includes(replyToLanguage)\n\n  if (hasLanguageSuggestion) {\n    return (\n      <GuessedLanguage\n        language={suggLang}\n        metadata={{currentTargetLanguages: currentLanguages, rawText: text}}\n        onAccept={onAccept}\n        onDecline={() => onDecline(suggLang)}\n      />\n    )\n  } else if (hasSuggestedReplyLanguage) {\n    return (\n      <ReplyLanguageNudge\n        language={replyToLanguage}\n        metadata={{currentTargetLanguages: currentLanguages}}\n        onAccept={onAccept}\n        onDecline={() => onDecline(replyToLanguage)}\n      />\n    )\n  } else {\n    return null\n  }\n}","file":"src/view/com/composer/select-language/SuggestedLanguage.tsx","kind":"component","line":102,"members":{"ax":[132,132],"config":[155,155],"currentLanguages":[102,131],"declinedSuggLangsRef":[135,135],"detectLanguage":[174,216],"detectionPropsRef":[160,163],"handleOnNudge":[169,169],"hasInteracted":[133,133],"onAccept":[140,144],"onAcceptSuggestedLanguage":[102,131],"onDecline":[145,150],"onNudge":[102,131],"replyToLanguage":[266,266],"replyToLanguagesProp":[102,131],"suggLang":[134,134],"text":[102,131]},"supers":[]},"composerReducer":{"appearsIn":[["composer","h-classes","Logic \u00b7 class diagram"],["composer","h-sequence","Write and publish a thread \u00b7 sequence"]],"code":"export function composerReducer(\n  state: ComposerState,\n  action: ComposerAction,\n): ComposerState {\n  switch (action.type) {\n    case 'update_postgate': {\n      return {\n        ...state,\n        isDirty: true,\n        thread: {\n          ...state.thread,\n          postgate: action.postgate,\n        },\n      }\n    }\n    case 'update_threadgate': {\n      return {\n        ...state,\n        isDirty: true,\n        thread: {\n          ...state.thread,\n          threadgate: action.threadgate,\n        },\n      }\n    }\n    case 'update_post': {\n      let nextPosts = state.thread.posts\n      const postIndex = state.thread.posts.findIndex(\n        p => p.id === action.postId,\n      )\n      if (postIndex !== -1) {\n        nextPosts = state.thread.posts.slice()\n        nextPosts[postIndex] = postReducer(\n          state.thread.posts[postIndex],\n          action.postAction,\n        )\n      }\n      return {\n        ...state,\n        isDirty: true,\n        thread: {\n          ...state.thread,\n          posts: nextPosts,\n        },\n      }\n    }\n    case 'add_post': {\n      const activePostIndex = state.activePostIndex\n      const nextPosts = [...state.thread.posts]\n      nextPosts.splice(activePostIndex + 1, 0, {\n        id: nanoid(),\n        richtext: new RichText({text: ''}),\n        shortenedGraphemeLength: 0,\n        labels: [],\n        embed: {\n          quote: undefined,\n          media: undefined,\n          link: undefined,\n        },\n      })\n      return {\n        ...state,\n        isDirty: true,\n        activePostIndex: activePostIndex + 1,\n        mutableNeedsFocusActive: true,\n        thread: {\n          ...state.thread,\n          posts: nextPosts,\n        },\n      }\n    }\n    case 'remove_post': {\n      if (state.thread.posts.length < 2) {\n        return state\n      }\n      let nextActivePostIndex = state.activePostIndex\n      const indexToRemove = state.thread.posts.findIndex(\n        p => p.id === action.postId,\n      )\n      let nextPosts = [...state.thread.posts]\n      if (indexToRemove !== -1) {\n        const postToRemove = state.thread.posts[indexToRemove]\n        if (postToRemove.embed.media?.type === 'video') {\n          postToRemove.embed.media.video.abortController.abort()\n        }\n        nextPosts.splice(indexToRemove, 1)\n        nextActivePostIndex = Math.max(0, indexToRemove - 1)\n      }\n      return {\n        ...state,\n        isDirty: true,\n        activePostIndex: nextActivePostIndex,\n        mutableNeedsFocusActive: true,\n        thread: {\n          ...state.thread,\n          posts: nextPosts,\n        },\n      }\n    }\n    case 'focus_post': {\n      const nextActivePostIndex = state.thread.posts.findIndex(\n        p => p.id === action.postId,\n      )\n      if (nextActivePostIndex === -1) {\n        return state\n      }\n      return {\n        ...state,\n        activePostIndex: nextActivePostIndex,\n      }\n    }\n    case 'restore_from_draft': {\n      const {\n        draftId,\n        posts,\n        threadgateAllow,\n        postgateEmbeddingRules,\n        loadedMedia,\n        originalLocalRefs,\n      } = action\n\n      return {\n        activePostIndex: 0,\n        mutableNeedsFocusActive: true,\n        draftId,\n        isDirty: false,\n        loadedMediaMap: loadedMedia,\n        originalLocalRefs,\n        thread: {\n          posts,\n          postgate: createPostgateRecord({\n            post: '',\n            embeddingRules: postgateEmbeddingRules,\n          }),\n          threadgate: threadgateRecordToAllowUISetting({\n            $type: 'app.bsky.feed.threadgate',\n            post: '' as AtUriString,\n            createdAt: toDatetimeString(new Date()),\n            allow: threadgateAllow,\n          }),\n        },\n      }\n    }\n    case 'clear': {\n      return createComposerState({\n        initText: undefined,\n        initMention: undefined,\n        initImageUris: [],\n        initQuoteUri: undefined,\n        initInteractionSettings: action.initInteractionSettings,\n      })\n    }\n    case 'mark_saved': {\n      return {\n        ...state,\n        isDirty: false,\n        draftId: action.draftId,\n      }\n    }\n  }\n}","file":"src/view/com/composer/state/composer.ts","kind":"function","line":193,"members":{},"supers":[]},"useComposerControls":{"appearsIn":[["composer","h-classes","Logic \u00b7 class diagram"],["composer","h-sequence","Write and publish a thread \u00b7 sequence"],["post-thread","h-classes","Logic \u00b7 class diagram"],["post-thread","h-sequence","Open a thread, reply \u00b7 sequence"]],"code":"export function useComposerControls() {\n  const {closeComposer} = useContext(controlsContext)\n  return useMemo(() => ({closeComposer}), [closeComposer])\n}","file":"src/state/shell/composer/index.tsx","kind":"hook","line":194,"members":{},"supers":[]},"useSaveDraftMutation":{"appearsIn":[["composer","h-classes","Logic \u00b7 class diagram"]],"code":"/**\n * Hook to save a draft.\n *\n * IMPORTANT: Network operations happen first in mutationFn.\n * Local storage operations (save new media, delete orphaned media) happen in onSuccess.\n * This ensures we don't lose data if the network request fails.\n */\nexport function useSaveDraftMutation() {\n  const client = useAppviewClient()\n  const chatClient = useChatClient()\n  const queryClient = useQueryClient()\n\n  return useMutation({\n    mutationFn: async ({\n      composerState,\n      existingDraftId,\n    }: {\n      composerState: ComposerState\n      existingDraftId?: string\n    }): Promise<{\n      draftId: string\n      draft: app.bsky.draft.defs.Draft\n      localRefPaths: Map<string, string>\n      originalLocalRefs: Set<string> | undefined\n    }> => {\n      // Convert composer state to server draft format\n      const {draft: apiDraft, localRefPaths} = await composerStateToDraft(\n        {appviewClient: client, chatClient},\n        composerState,\n      )\n      const draft = apiDraft\n\n      logger.debug('saving draft', {\n        existingDraftId,\n        localRefPathCount: localRefPaths.size,\n        originalLocalRefCount: composerState.originalLocalRefs?.size ?? 0,\n      })\n\n      // 1. NETWORK FIRST - Update/create server draft\n      let draftId: string\n      if (existingDraftId) {\n        // Update existing draft\n        logger.debug('updating existing draft on server', {\n          draftId: existingDraftId,\n        })\n        await client.call(app.bsky.draft.updateDraft, {\n          draft: {\n            id: existingDraftId,\n            draft,\n          },\n        })\n        draftId = existingDraftId\n      } else {\n        // Create new draft\n        logger.debug('creating new draft on server')\n        const data = await client.call(app.bsky.draft.createDraft, {draft})\n        draftId = data.id\n        logger.debug('created new draft', {draftId})\n      }\n\n      // Return data needed for onSuccess\n      return {\n        draftId,\n        draft,\n        localRefPaths,\n        originalLocalRefs: composerState.originalLocalRefs,\n      }\n    },\n    onSuccess: async ({draftId, draft, localRefPaths, originalLocalRefs}) => {\n      // 2. LOCAL STORAGE ONLY AFTER NETWORK SUCCEEDS\n      logger.debug('network save succeeded, processing local storage', {\n        draftId,\n      })\n\n      // Save new/changed media files\n      for (const [localRefPath, sourcePath] of localRefPaths) {\n        // Only save if this media doesn't already exist (reusing localRefPath)\n        if (!storage.mediaExists(localRefPath)) {\n          logger.debug('saving new media file', {localRefPath})\n          await storage.saveMediaToLocal(localRefPath, sourcePath)\n        } else {\n          logger.debug('skipping existing media file', {localRefPath})\n        }\n      }\n\n      // Delete orphaned media (old refs not in new)\n      if (originalLocalRefs) {\n        const newLocalRefs = new Set(localRefPaths.keys())\n        for (const oldRef of originalLocalRefs) {\n          if (!newLocalRefs.has(oldRef)) {\n            logger.debug('deleting orphaned media file', {\n              localRefPath: oldRef,\n            })\n            await storage.deleteMediaFromLocal(oldRef)\n          }\n        }\n      }\n\n      /*\n       * Saves are acknowledged before the drafts index catches up. For edits,\n       * finding the ID alone can still return the previous contents. Normalize\n       * optional fields the same way as the JSON sent to the server.\n       */\n      const expectedDraft = lexToJson(draft)\n      const didObserveSave = await until(\n        5,\n        1e3,\n        data =>\n          data?.drafts.some(\n            view =>\n              view.id === draftId &&\n              lexEquals(lexToJson(view.draft), expectedDraft),\n          ) ?? false,\n        () => client.call(app.bsky.draft.getDrafts, {limit: 100}),\n      )\n      if (!didObserveSave) {\n        /*\n         * The write already succeeded. Failing the mutation here would invite\n         * retrying a create and saving a duplicate draft.\n         */\n        logger.warn('Saved draft not yet visible in drafts list', {draftId})\n      }\n\n      await queryClient.invalidateQueries({queryKey: DRAFTS_QUERY_KEY})\n    },\n    onError: error => {\n      // Check for draft limit error\n      if (matchXrpcError(error, app.bsky.draft.createDraft)) {\n        logger.error('Draft limit reached', {safeMessage: error.message})\n        // Error will be handled by caller\n      } else if (!isNetworkError(error)) {\n        logger.error('Could not create draft (reason unknown)', {\n          safeMessage: error.message,\n        })\n      }\n    },\n  })\n}","file":"src/view/com/composer/drafts/state/queries.ts","kind":"hook","line":119,"members":{"chatClient":[128,128],"client":[127,127],"queryClient":[129,129]},"supers":[]}},"sourceUrl":"https://github.com/bluesky-social/social-app/blob/f7399a645c08dcf5d15f8cac64417ac73fe6ddf9/"};
